def check_solution(a, b, c):
    left = 2**a + 3**b + 1
    right = 6**c
    return left == right

solutions = []
for c in range(1, 4):
    for b in range(1, 5):
        for a in range(1, 6):
            if check_solution(a, b, c):
                solutions.append((a, b, c))

print(f"Found solutions (a, b, c): {solutions}")
